import math

def count_divisors(n):
    """Calculates the total number of positive divisors, tau(n)."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Calculates the number of positive divisors of n other than 1 and itself."""
    if n <= 1:
        return -1 # Undefined or handle as appropriate, but n >= 1
    tau_n = count_divisors(n)
    return tau_n - 2

